public class KeyValueOptionParserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static final String[] ARGS = {"run", "--mode=fast", "--retries=3", "--mode=slow", "--quiet"};

    public static void main(String[] args) {
        try {
            check("valueOf(mode) -- first wins", "fast", KeyValueOptionParser.valueOf(ARGS, "mode"));
            check("valueOf(retries)", "3", KeyValueOptionParser.valueOf(ARGS, "retries"));
            check("valueOf(colour) -- missing", null, KeyValueOptionParser.valueOf(ARGS, "colour"));
            check("valueOf(quiet) -- no equals sign is not a match", null,
                    KeyValueOptionParser.valueOf(ARGS, "quiet"));
            check("valueOf with empty value", "",
                    KeyValueOptionParser.valueOf(new String[] {"--mode="}, "mode"));
            check("value may contain an equals sign", "a=b",
                    KeyValueOptionParser.valueOf(new String[] {"--filter=a=b"}, "filter"));
            check("valueOf on empty args", null, KeyValueOptionParser.valueOf(new String[] {}, "mode"));

            check("intValueOf(retries, 1)", 3, KeyValueOptionParser.intValueOf(ARGS, "retries", 1));
            check("intValueOf(mode, 1) -- not a number", 1, KeyValueOptionParser.intValueOf(ARGS, "mode", 1));
            check("intValueOf(timeout, 9) -- missing", 9, KeyValueOptionParser.intValueOf(ARGS, "timeout", 9));
            check("intValueOf with a negative value", -5,
                    KeyValueOptionParser.intValueOf(new String[] {"--offset=-5"}, "offset", 0));
        } catch (RuntimeException ex) {
            System.out.println("FAIL  a method threw " + ex);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

